"""Auto-generated Markdown report generator with mandatory limitations section (SYS-16, SYS-17)."""

from __future__ import annotations

from typing import Any

from autogen.analytics.hypothesis import HypothesisTestResult
from autogen.analytics.statistics import SampleStats


class MarkdownReportGenerator:
    """Generates publication-quality Markdown experimental reports."""

    @staticmethod
    def generate_report(
        experiment_name: str,
        config_hash: str,
        git_commit: str,
        total_episodes: int,
        metrics: dict[str, SampleStats],
        comparisons: list[HypothesisTestResult] | None = None,
        ablation_table: list[dict[str, Any]] | None = None,
        runtime_seconds: float = 0.0,
        throughput_ticks_per_sec: float = 0.0,
        known_confounds: list[str] | None = None,
    ) -> str:
        lines: list[str] = [
            f"# Experimental Report: {experiment_name}",
            "",
            "> **Generated by AUTOGEN Analytics & Experiment Engine (SYS-16, SYS-17)**",
            "",
            "## 1. Executive Summary & Provenance",
            f"- **Experiment Name:** `{experiment_name}`",
            f"- **Configuration Hash:** `{config_hash}`",
            f"- **Git Commit:** `{git_commit}`",
            f"- **Evaluated Episodes / Seeds:** {total_episodes}",
            f"- **Total Wall Time:** {runtime_seconds:.2f} seconds",
            f"- **Simulation Throughput:** {throughput_ticks_per_sec:.1f} ticks/second",
            "",
            "## 2. Quantitative Performance Metrics",
            "| Metric | N | Mean | 95% CI (Student-t) | Median | IQR | Std Dev | Std Error |",
            "| :--- | :---: | :---: | :---: | :---: | :---: | :---: | :---: |",
        ]

        for m_name, s in metrics.items():
            lines.append(
                f"| `{m_name}` | {s.n} | {s.mean:.4f} | [{s.ci_lower:.4f}, {s.ci_upper:.4f}] | "
                f"{s.median:.4f} | {s.iqr:.4f} | {s.std_dev:.4f} | {s.standard_error:.4f} |"
            )

        if comparisons:
            lines.extend([
                "",
                "## 3. Hypothesis Testing & Effect Sizes",
                "| Comparison / Test | Statistic | p-value | Significance (alpha=0.05) | Effect Size (Cohen's d) | Assumptions Met | Verdict |",
                "| :--- | :---: | :---: | :---: | :---: | :---: | :--- |",
            ])
            for comp in comparisons:
                sig_str = "YES (p <= alpha)" if comp.is_significant else "NO (p > alpha)"
                assump_str = "Yes" if comp.assumptions_satisfied else "Violated (Permutation Used)"
                lines.append(
                    f"| {comp.test_name} | {comp.statistic:.4f} | {comp.p_value:.4e} | {sig_str} | "
                    f"{comp.effect_size:.3f} | {assump_str} | {comp.verdict} |"
                )

        if ablation_table:
            lines.extend([
                "",
                "## 4. Component Ablation Analysis",
                "| Configuration / Ablation | Mean Return | 95% CI | Survival Rate | Effect Size vs Full (Cohen's d) | Status |",
                "| :--- | :---: | :---: | :---: | :---: | :--- |",
            ])
            for row in ablation_table:
                cfg_name = row.get("name", "Unknown")
                m_ret = row.get("mean_return", 0.0)
                ci_str = row.get("ci_str", "N/A")
                sr = row.get("survival_rate", 0.0)
                cd = row.get("cohens_d", 0.0)
                status = row.get("status", "Evaluated")
                lines.append(
                    f"| `{cfg_name}` | {m_ret:.2f} | {ci_str} | {sr * 100:.1f}% | {cd:.2f} | {status} |"
                )

        # Mandatory Limitations Section
        limitations: list[str] = []
        if total_episodes < 30:
            limitations.append(
                f"Low sample size warning: Only {total_episodes} seeds were evaluated. Central Limit Theorem asymptotic normality is weakly guaranteed; non-parametric checks should be preferred."
            )
        if comparisons:
            for c in comparisons:
                if not c.assumptions_satisfied:
                    limitations.append(
                        f"Distribution normality violated for {c.test_name}; non-parametric permutation statistics were substituted."
                    )
        if known_confounds:
            limitations.extend(known_confounds)
        else:
            limitations.append(
                "Evaluations performed on discrete 2D grid world environments; continuous dynamics and multi-agent partial observability extensions require dedicated validation."
            )

        lines.extend([
            "",
            "## 5. Mandatory Limitations & Scientific Threats to Validity",
            "> [!WARNING] Mandatory Methodology Disclosure",
        ])
        for idx, lim in enumerate(limitations, 1):
            lines.append(f"{idx}. {lim}")

        lines.extend([
            "",
            "---",
            "*Report generated deterministically from immutable RunRecords.*",
            "",
        ])

        return "\n".join(lines)

